pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint96 amount) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0);
        vm.deal(actor, uint256(amount) * 2);

        vm.prank(actor);
        c.deposit{value: amount}();

        vm.prank(actor);
        c.withdrawAll();

        // General rule: after withdrawAll completes, the caller's credit is cleared,
        // so credit(actor) == 0. The mutant leaves credit unchanged.
        assertTrue(c.credit(actor) == 0, "credit must be cleared after withdrawAll");
    }
}

