pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actorA, address actorB) public {
        vm.assume(amount > 0 && amount < 1 ether * 1000000);
        vm.assume(actorA != address(0) && actorB != address(0) && actorA != actorB);
        vm.assume(actorA.code.length == 0 && actorB.code.length == 0);

        vm.deal(actorA, amount);
        vm.prank(actorA);
        c.deposit{value: amount}();

        vm.deal(actorB, amount);
        vm.prank(actorB);
        c.deposit{value: amount}();

        // A withdraws, then tries again (mutant pays out a second time, draining B's share)
        vm.prank(actorA);
        c.withdrawAll();
        vm.prank(actorA);
        c.withdrawAll();

        // B must still be able to withdraw its credited funds
        bool okB;
        vm.prank(actorB);
        try c.withdrawAll() { okB = true; } catch { okB = false; }

        assertTrue(okB);
    }
}

