pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public {
        c = new C();
        attacker = new Attacker(c);
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1 wei, 100 ether);
        vm.deal(address(attacker), amount);
        attacker.deposit{value: amount}();
        bool ok;
        try attacker.attack() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract Attacker {
    C c;
    constructor(C _c) { c = _c; }

    function deposit() external payable {
        c.deposit{value: msg.value}();
    }

    function attack() external {
        c.withdrawAll();
    }

    // re-entrant call during the external call; low-level so failures don't bubble
    receive() external payable {
        address(c).call(abi.encodeWithSignature("withdrawAll()"));
    }
}

