pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(c));
        vm.assume(actor.code.length == 0);
        amount = bound(amount, 1, type(uint256).max / 2);

        Reverter r = new Reverter();

        // actor deposits `amount` into c
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();
        uint256 initialBalance = address(c).balance;

        // the reverter contract withdraws: the low-level transfer to it fails
        vm.prank(address(r));
        try c.withdrawAll() { } catch { }

        // Rule: deposited funds are conserved - they sit in c or reach the
        // withdrawer. The reference reverts on the failed send (nothing lost);
        // the mutant zeroes the credit and drops c's balance while the
        // reverter receives nothing.
        assertTrue(address(c).balance + address(r).balance == initialBalance);
    }
}

