        amount = bound(amount, 0, type(uint256).max / 2);
        ReentrantDepositor attacker = new ReentrantDepositor(c);
        vm.deal(address(attacker), amount);
        attacker.depositAndWithdraw(amount);
        // Reference: withdrawAll pays oCredit to the caller; the caller re-deposits it,
