contract ReentrantDepositor {
    C c;
    constructor(C c_) { c = c_; }
    function depositAndWithdraw(uint256 amount) external {
        c.deposit{value: amount}();
        c.withdrawAll();
    }
    receive() external payable {
        if (msg.value > 0) c.deposit{value: msg.value}();
    }
}

